# Check bounding boxes of components in demo 1
from collections import deque

def get_components_with_boxes(grid):
    H, W = len(grid), len(grid[0])
    visited = [[False] * W for _ in range(H)]

    for i in range(H):
        for j in range(W):
            if not visited[i][j] and grid[i][j] != 1:
                c = grid[i][j]
                q = deque([(i, j)])
                visited[i][j] = True
                comp_cells = []

                while q:
                    y, x = q.popleft()
                    comp_cells.append((y, x))
                    for dy, dx in [(1,0), (-1,0), (0,1), (0,-1)]:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and not visited[ny][nx] and grid[ny][nx] == c:
                            visited[ny][nx] = True
                            q.append((ny, nx))

                ys = [p[0] for p in comp_cells]
                xs = [p[1] for p in comp_cells]

                # Determine if it's filled as a solid block in output
                is_filled = True
                for y in range(min(ys), max(ys)+1):
                    for x in range(min(xs), max(xs)+1):
                        if (y, x) not in comp_cells:
                            is_filled = False
                            break

                return c, len(comp_cells), ys, xs, comp_cells, is_filled

